questionvariables.text:
/* Design: how many points two loci share. Rows ["cc", r1, r2, d] (two circles) or ["cl", r, p] (circle and line); categories 1 none, 2 one, 3 two. Every entry has all three answers, a circle-inside-circle row (never first), a touching row and a circle-line row. No row repeats the chapter's examples or exercises. Source: original. */
q63: [[[["cc",6,8,8],["cl",5,6],["cc",9,3,2],["cc",7,3,10]],[3,1,1,2]],[[["cl",8,9],["cc",7,5,9],["cc",8,3,2],["cc",3,5,8]],[1,3,1,2]],[[["cc",8,5,5],["cc",4,3,0],["cc",4,4,8],["cl",6,8]],[3,1,2,1]],[[["cl",5,6],["cc",7,7,1],["cc",7,3,3],["cc",8,3,5]],[1,3,1,2]],[[["cc",4,5,4],["cc",6,2,0],["cc",5,4,9],["cl",7,8]],[3,1,2,1]],[[["cc",8,3,9],["cl",8,8],["cc",7,2,3],["cc",7,6,1]],[3,2,1,2]],[[["cl",4,5],["cc",7,6,5],["cc",5,3,8],["cc",4,3,0]],[1,3,2,1]],[[["cc",3,8,8],["cl",8,8],["cc",8,2,10],["cc",5,3,0]],[3,2,2,1]],[[["cc",8,8,1],["cc",7,3,1],["cc",5,5,10],["cl",8,10]],[3,1,2,1]],[[["cl",3,4],["cc",4,6,5],["cc",5,6,11],["cc",4,2,0]],[1,3,2,1]]];
ix: 1+rand(10);
rw: q63[ix][1]; cats: q63[ix][2];
keys: ["none","one","two"];
kyl: makelist(keys[cats[k]], k, 1, 4);
/* row type: 1 one circle inside the other; 2 circles touching; 3 circle and line; 4 other two circles */
ty: makelist(if is(rw[k][1]="cl") then 3 else if is(rw[k][4]<abs(rw[k][2]-rw[k][3])) then 1 else if is(rw[k][4]=rw[k][2]+rw[k][3] or rw[k][4]=abs(rw[k][2]-rw[k][3])) then 2 else 4, k, 1, 4);
/* diagnostic answer per row: inside and touching rows "two"; other rows the opposite extreme */
dg: makelist(if is(ty[k]<=2) then "two" else if is(kyl[k]="none") then "two" else "none", k, 1, 4);
/* generic wrong answer per row (tests): the category that is neither right nor the diagnostic */
gw: makelist(first(sublist(keys, lambda([z], is(z#kyl[k]) and is(z#dg[k])))), k, 1, 4);
mko(c) := [["none",is(c=1),"no points"],["one",is(c=2),"exactly one point"],["two",is(c=3),"two points"]];
o1: mko(cats[1]); o2: mko(cats[2]); o3: mko(cats[3]); o4: mko(cats[4]);
ta1: kyl[1]; ta2: kyl[2]; ta3: kyl[3]; ta4: kyl[4];
